import { focus, pxToRem, visuallyHidden } from "../../helpers";
import { StyleFn } from "..";

export const Toggle: StyleFn = (theme, mode) => {
  const { color, elevation, font, opacity, size } = theme;
  const { focusWithPseudo } = focus(theme, mode);

  // FIXME add size.spacing[18] token ?
  const defaultAfterSize = pxToRem(18);

  return {
    root: {
      extend: [
        focusWithPseudo({
          radius: pxToRem(40),
          width: size.spacing[56],
          focusSelector: "has(input:focus-visible)",
        }),
      ],
      display: "inline-flex",
      alignItems: "center",
      position: "relative",
    },
    input: {
      extend: [visuallyHidden()],
      position: "absolute",
      "&:checked + $label:before": {
        border: "none",
        background: color.surface.accent.default[mode],
      },
      "&:checked + $label:hover:before": {
        background: color.surface.accent.hover[mode],
      },
      "&:checked + $label:after": {
        left: pxToRem(27),
        background: color.surface.interaction.default[mode],
      },
      "&:disabled + $label": {
        opacity: opacity.disabled,
      },
    },
    label: {
      display: "inline-flex",
      position: "relative",
      margin: 0,
      padding: 0,
      paddingLeft: `calc(${size.spacing[48]} + ${size.spacing[8]})`,
      fontSize: font.size.medium,
      lineHeight: size.spacing[24],
      height: size.spacing[24],
      color: color.text.neutral.default[mode],
      "&:hover": {
        cursor: "pointer",
        "&:before": {
          background: color.surface.interaction.hover[mode],
        }
      },
      "&:before": {
        content: "''",
        position: "absolute",
        display: "inline-block",
        width: size.spacing[48],
        height: size.spacing[24],
        left: 0,
        top: 0,
        borderRadius: pxToRem(40),
        background: color.surface.interaction.default[mode],
        border: `1px solid ${color.border.accent.corporate[mode]}`,
      },
      "&:after": {
        content: "''",
        position: "absolute",
        display: "inline-block",
        // TODO: create some new spacing tokens?
        top: pxToRem(3),
        left: pxToRem(3),
        width: defaultAfterSize,
        height: defaultAfterSize,
        borderRadius: "50%",
        transition: "left 0.25s",
        background: color.surface.accent.default[mode],
        boxShadow: elevation.level2, //"0 2px 8px 0 rgba(0,0,0,0.20)",
      },
    },
    label_none: {
      paddingLeft: size.spacing[48],
    },
    _large: {
      "&:has(input:focus-visible):after": { width: size.spacing[72] },
      "& > $label": {
        fontSize: font.size.large,
        lineHeight: size.spacing[32],
        height: size.spacing[32],
        paddingLeft: `calc(${size.spacing[64]} + ${size.spacing[8]})`,
      },
      "& > $label_none": {
        paddingLeft: size.spacing[64],
      },
      "& > $label:before": {
        width: size.spacing[64],
        height: size.spacing[32],
      },
      "& > $label:after": {
        top: size.spacing[4],
        left: size.spacing[4],
        width: size.spacing[24],
        height: size.spacing[24],
      },
      "& > $input:checked + $label:after": {
        left: `calc(${size.spacing[32]} + ${size.spacing[4]})`,
      },
    },
    _small: {
      "&:has(input:focus-visible):after": { width: size.spacing[40] },
      "& > $label": {
        fontSize: font.size.small,
        lineHeight: size.spacing[16],
        height: size.spacing[16],
        paddingLeft: `calc(${size.spacing[32]} + ${size.spacing[8]})`,
      },
      "& > $label_none": {
        paddingLeft: size.spacing[32],
      },
      "& > $label:before": {
        width: size.spacing[32],
        height: size.spacing[16],
      },
      "& > $label:after": {
        top: size.spacing[2],
        left: size.spacing[2],
        width: size.spacing[12],
        height: size.spacing[12],
      },
      "& > $input:checked + $label:after": {
        left: defaultAfterSize,
      },
    },
  };
};
